/**
 * corpus.test.ts — byte-equality conformance for the TS GTS builder.
 *
 * Verifies buildGts() against strokes-level fixtures generated by the Python
 * reference (gts_api.build_gts). These isolate the binary builder from the
 * translator/optimiser. The full from_gcode golden corpus (tests/golden/)
 * gets wired in once the translator and optimiser are ported.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { createHash } from 'node:crypto';
import { buildGts, type Stroke } from '../src/gts.ts';

const here = dirname(fileURLToPath(import.meta.url));
const fixtures = JSON.parse(
  readFileSync(join(here, 'fixtures', 'build_gts_fixtures.json'), 'utf8'),
) as {
  cases: Record<string, {
    strokes: [number, number, [number, number][]][];
    opts: { speed?: number; pz?: number; dz?: number };
    expected_hex: string;
    sha256: string;
    bytes: number;
  }>;
};

function toStrokes(raw: [number, number, [number, number][]][]): Stroke[] {
  return raw.map(([sx, sy, deltas]) => ({ start: [sx, sy], deltas }));
}

function hex(u: Uint8Array): string {
  return Array.from(u, (b) => b.toString(16).padStart(2, '0')).join('');
}

for (const [name, c] of Object.entries(fixtures.cases)) {
  test(`buildGts byte-exact: ${name}`, () => {
    const got = buildGts(toStrokes(c.strokes), c.opts);
    assert.equal(got.length, c.bytes, 'length mismatch');
    assert.equal(hex(got), c.expected_hex, 'byte mismatch vs Python build_gts');
    // Cross-language fingerprint: TS output hash must equal the manifest's,
    // which Python computed. Redundant with the byte compare but is the
    // compact contract both sides point at.
    const digest = createHash('sha256').update(got).digest('hex');
    assert.equal(digest, c.sha256, 'sha256 mismatch vs Python manifest');
  });
}

test('buildGts throws on empty strokes', () => {
  assert.throws(() => buildGts([]), /empty/);
});
